import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on t-statistics and effect sizes
    drivers = []
    strong_features = []

    # Filter features with |t| > 3.0 or |mean_y1-mean_y0| > 0.2
    for i, fid in enumerate(feats.ids):
        # Use the actual t-statistic from the data
        try:
            t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic)
        except:
            t_stat = 0
        if t_stat > 3.0 or abs(feats.x[:, i].mean()) > 0.2:
            strong_features.append(fid)

    # Look for correlated pairs with high correlation (>0.6)
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if i != j:
                try:
                    corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                except:
                    corr = 0
                if abs(corr) >= 0.6:
                    correlations[(fid1, fid2)] = abs(corr)

    # Prioritize features with highest t-statistics
    t_stats = []
    for i, fid in enumerate(feats.ids):
        try:
            t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic)
        except:
            t_stat = 0
        t_stats.append((fid, t_stat))

    t_stats.sort(key=lambda x: x[1], reverse=True)

    # Select top features for drivers
    selected_drivers = set()
    for fid, _ in t_stats[:10]:  # Top 10 features by t-stat
        if len(selected_drivers) >= MAX_DRIVERS:
            break
        if fid in strong_features:
            selected_drivers.add(fid)

    # Check for interaction terms among highly correlated features
    candidates = list(selected_drivers)
    products = []

    # Check for products between features that are strongly correlated
    for fid1 in candidates:
        for fid2 in candidates:
            if fid1 < fid2:
                # Check if they're in our correlation list
                pair = (fid1, fid2) if fid1 < fid2 else (fid2, fid1)
                if pair in correlations:
                    products.append((fid1, fid2))

    # If we have strong interactions, include them
    if products:
        return Design(
            drivers=tuple(list(selected_drivers)[:MAX_DRIVERS]),
            columns=tuple(list(selected_drivers)),
            products=tuple(products),
            loadings={}
        )

    # Otherwise, use simple approach
    # Select features with significant effect size
    columns = []
    for i, fid in enumerate(feats.ids):
        if abs(feats.x[:, i].mean()) > 0.15:  # Effect size threshold
            columns.append(fid)

    # If no clear mechanism, return empty drivers
    if not columns:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Simple weighted score based on effect sizes
    loadings = {}
    for i, fid in enumerate(feats.ids):
        loadings[fid] = abs(feats.x[:, i].mean())

    # Normalize loadings
    total = sum(loadings.values())
    if total > 0:
        for fid in loadings:
            loadings[fid] /= total

    return Design(
        drivers=tuple(list(selected_drivers)[:MAX_DRIVERS]),
        columns=tuple(columns),
        products=(),
        loadings=loadings
    )
